#include <algorithm>
#include <list>

void* operator new(unsigned int, unsigned int, const char*, int);
#define NEW new(0,__PRETTY_FUNCTION__,0)

class signal
{
public:
  typedef list<signal*> signal_list;

protected:
  int flavor;

private:
  unsigned int flags;
  const char* name;
  signal_list* outputs;
  list<void*> callbacks;

public:
  void link( signal* s );
};

void signal::link( signal* s )
{
  if ( outputs == NULL )
    outputs = NEW signal_list;
  signal_list::const_iterator i = find( outputs->begin(), outputs->end(), s );
  if ( i == outputs->end() )
    outputs->push_front( s );
}
